#!/usr/bin/env python3
# Onyx: makes onyx_propbits.h from autogenerated_propget.h -- the computed style's bits
# (index, mask) of the paint properties css_computed_style_paint_only_change (arena.c) reads.
# Run it after select_generator.py whenever select_config.py changes the layout:
#   cd third_party/libcss/src/select && python3 -B select_generator.py && python3 onyx_propbits.py
import os, re
here = os.path.dirname(os.path.realpath(__file__))
PAINT = ['color', 'background_color', 'background_image', 'background_attachment',
         'background_clip', 'background_repeat', 'background_position', 'background_size',
         'border_top_color', 'border_right_color', 'border_bottom_color', 'border_left_color',
         'border_top_left_radius', 'border_top_right_radius', 'border_bottom_left_radius',
         'border_bottom_right_radius', 'box_shadow', 'text_shadow', 'column_rule_color',
         'outline_color', 'outline_style', 'outline_width', 'text_decoration', 'visibility',
         'opacity', 'fill_opacity', 'stroke_opacity', 'z_index', 'cursor', 'rotate', 'scale',
         'transform', 'translate',
         'fill', 'stroke', 'stroke_width', 'stroke_dasharray', 'stroke_dashoffset',
         'stroke_linecap', 'stroke_linejoin', 'stroke_miterlimit', 'fill_rule',
         'stop_color', 'stop_opacity']
src = open(os.path.join(here, 'autogenerated_propget.h')).read()
out = ['/*',
       ' * onyx_propbits.h -- Onyx: the computed style\'s bits (index, mask) of the paint properties,',
       ' * copied from autogenerated_propget.h (which #undefs them after each getter), for',
       ' * css_computed_style_paint_only_change (arena.c). Made by onyx_propbits.py: run it again',
       ' * (after select_generator.py) if select_config.py changes the layout.',
       ' */',
       '#ifndef ONYX_PROPBITS_H', '#define ONYX_PROPBITS_H', '']
for p in PAINT:
    u = p.upper()
    i = re.search(r'#define %s_INDEX (\d+)' % u, src)
    m = re.search(r'#define %s_MASK (0x[0-9a-f]+)' % u, src)
    if not i or not m:
        raise SystemExit('onyx_propbits.py: no bits for ' + p)
    out.append('#define ONYX_%s_INDEX %s' % (u, i.group(1)))
    out.append('#define ONYX_%s_MASK %s' % (u, m.group(1)))
out += ['', '#endif', '']
open(os.path.join(here, 'onyx_propbits.h'), 'w').write('\n'.join(out))
